python3 << 'PYEOF'
import json

fpath = "/home/ubuntu/.claude-account-5/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-10-projects-provenance-weight-training/d73ed364-191f-4186-82bb-d624f4b188dc/tool-results/mcp-agent-ml-research-read_registry-1778892601784.txt"

with open(fpath, 'r') as f:
    raw = f.read()

outer = json.loads(raw)
inner = json.loads(outer['result'])
experiments = inner['data']['experiments']

# For each experiment, find all metric-like fields (eval_ppl, etc.)
for eid in sorted(experiments.keys()):
    exp = experiments[eid]
    # Search for ppl-related keys at top level and in spec
    ppl_fields = {}
    for k, v in exp.items():
        if 'ppl' in str(k).lower() or 'eval' in str(k).lower():
            ppl_fields[k] = v
    if 'spec' in exp:
        for k, v in exp['spec'].items():
            if 'ppl' in str(k).lower() or 'eval' in str(k).lower():
                ppl_fields[f'spec.{k}'] = v
    if 'metrics' in exp:
        ppl_fields['metrics'] = exp['metrics']
    if 'results' in exp:
        ppl_fields['results'] = exp['results']

    print(f"\n=== {eid} ===")
    print(json.dumps(ppl_fields, indent=2, default=str)[:1000])
PYEOF

